#include "PerceptionErrorCorrector.h"
#include <algorithm>
namespace dnxr { FullDiveNeuralFrame PerceptionErrorCorrector::correct(const FullDiveNeuralFrame& frame, float err, double dt, const PerceptionCorrectionPolicy& p) const { FullDiveNeuralFrame out=frame; if(err>0.75f){ out.safety.aggregateRisk=1.0f; return out; } const float corr=std::clamp(err*p.patientLearningRate, -p.antiRunawayClamp, std::min(p.antiRunawayClamp, p.maxCorrectionPerSecond*static_cast<float>(dt))); auto adjust=[corr](auto& layer){ for(auto& c:layer.channels) c.intensity=std::clamp(c.intensity-corr,0.0f,c.safetyLimit>0?c.safetyLimit:1.0f); }; adjust(out.visual); adjust(out.auditory); adjust(out.somatosensory); adjust(out.proprioception); adjust(out.vestibular); adjust(out.smellTaste.olfactory); adjust(out.smellTaste.gustatory); return out; } }
